  'review_rejected',
  'council_opened',
  'council_split',
  'arbiter_decision',
  'urgent_alert'
];

export function parseCouncilComments(comments) {
  const results = [];
  for (const comment of comments) {
    const lines = comment.body.split('\n');
    for (const line of lines) {
      const trimmed = line.trim();
      const match = trimmed.match(/^\[(\w+-?\w*)\](.*)$/);
      if (!match) continue;
      const marker = match[1];
      if (!MARKERS.includes(marker)) continue;
      const rest = match[2].trim();
      const fields = {};
      const pairs = rest.split(/\s+/);
      for (const pair of pairs) {
        const eq = pair.indexOf('=');
        if (eq > 0) {
          const key = pair.substring(0, eq);
          const value = pair.substring(eq + 1);
          fields[key] = value;
        }
      }
      results.push({
        marker,
        fields,
        comment_id: comment.id,
        seat: fields.seat || null,
        round: fields.round ? parseInt(fields.round, 10) : null,
        raw: trimmed
      });
    }
  }
  return results;
}

export function evaluateCouncil({
  taskId,
  comments,
  requiredSeats = ['relay-claude', 'relay-gpt'],
  maxRounds = 2,
  reserved = false
}) {
  const parsed = parseCouncilComments(comments);
  const objections = parsed.filter(p => p.marker === 'objection');
  const proposals = parsed.filter(p => p.marker === 'proposal');
  const concurs = parsed.filter(p => p.marker === 'concur');
  const reviews = parsed.filter(p => p.marker === 'review');
  const councils = parsed.filter(p => p.marker === 'council');
  const consensuses = parsed.filter(p => p.marker === 'consensus');

  let blocking = 0;
  for (const obj of objections) {
    if (obj.fields.severity === 'blocking') {
      const objRound = obj.round || 0;
      const hasLaterProposal = proposals.some(p => (p.round || 0) >= objRound && p.comment_id > obj.comment_id);
      const hasConcur = concurs.some(c => c.fields.target == obj.comment_id);
      if (!hasLaterProposal && !hasConcur) {
        blocking++;
      }
    }
  }

  if (blocking > 0) {
    return {
      stage: 'revision_required',
      round: Math.max(...parsed.map(p => p.round || 0), 0),
      consensus: false,
      blocking,
      next: 'revision_required',
      reason: 'blocking objection unresolved'
    };
  }

  const reviewsBySeats = {};
  for (const r of reviews) {
    if (r.seat) {
      if (!reviewsBySeats[r.seat]) reviewsBySeats[r.seat] = [];
      reviewsBySeats[r.seat].push(r);
    }
  }

  const latestReviews = {};
  for (const seat of requiredSeats) {
    const seatReviews = reviewsBySeats[seat] || [];
    if (seatReviews.length > 0) {
      latestReviews[seat] = seatReviews[seatReviews.length - 1];
    }
  }

  const reviewCount = Object.keys(latestReviews).length;
  if (reserved && reviewCount < requiredSeats.length) {
    return {
      stage: 'wait',
      round: Math.max(...parsed.map(p => p.round || 0), 0),
      consensus: false,
      blocking: 0,
      next: 'wait',
      reason: 'reserved mode requires all seats'
    };
  }

  const verdicts = Object.values(latestReviews).map(r => r.fields.verdict);
  const allPass = verdicts.length > 0 && verdicts.every(v => v === 'pass');
  const allFail = verdicts.length > 0 && verdicts.every(v => v === 'fail');
  const split = verdicts.length > 0 && !allPass && !allFail;

  const currentRound = Math.max(...parsed.map(p => p.round || 0), 0);

  if (split || (reviewCount === 1 && !reserved)) {
    if (councils.length > 0 && currentRound >= maxRounds) {
      return {
        stage: 'council',
        round: currentRound,
        consensus: false,
        blocking: 0,
        next: 'arbitrate',
        reason: 'council rounds exhausted'
      };
    }
    return {
      stage: 'council',
      round: currentRound,
      consensus: false,
      blocking: 0,
      next: 'open_council',
      reason: 'reviews split or insufficient'
    };
  }

  const latestConsensus = consensuses.length > 0 ? consensuses[consensuses.length - 1] : null;
  if (latestConsensus && latestConsensus.fields.result === 'split' && currentRound >= maxRounds) {
    return {
      stage: 'council',
      round: currentRound,
      consensus: false,
      blocking: 0,
      next: 'arbitrate',
      reason: 'consensus split at max rounds'
    };
  }

  if (allPass && reviewCount === requiredSeats.length) {
    return {
      stage: 'approved',
      round: currentRound,
      consensus: true,
      blocking: 0,
      next: 'approve',
      reason: 'all required seats pass'
    };
  }

  return {
    stage: 'wait',
    round: currentRound,
    consensus: allPass,
    blocking: 0,
    next: 'wait',
    reason: 'awaiting reviews'
  };
}

export function wakeDecision({ taskId, event, sourceId, now, recent = [] }) {
  const dedupe_key = `${taskId}:${event}:${sourceId}`;

  if (recent.some(r => r.dedupe_key === dedupe_key)) {
    return {
      wake: false,
      reason: 'duplicate',
      dedupe_key,
      suppressed: true
    };
  }

  const oneHourAgo = now - 3600000;
  const taskRecent = recent.filter(r => r.taskId === taskId && r.timestamp > oneHourAgo);
  if (taskRecent.length >= 1) {
    return {
      wake: false,
      reason: 'task_rate_limited',
      dedupe_key,
      suppressed: true
    };
  }

  if (recent.length >= 6) {
    return {
      wake: false,
      reason: 'global_rate_limited',
      dedupe_key,
      suppressed: true
    };
  }

  return {
    wake: true,
    reason: 'wake',
    dedupe_key,
    suppressed: false
  };
}
